const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],message='';
export function swarmView(){return `<div class="eyebrow">SWARM / AUTOMATA</div><h1>Reduce. Reconstruct. Analyze. Route.</h1><p class="lede">A pure JavaScript pipeline with five execution partitions and a local evidence record.</p><div class="notes-grid"><section class="card"><h2>Source to analyze</h2><p class="notice">Runs on your computer with Node.js 22+. Source files stay local. JavaScript is syntax-checked and analyzed as data.</p><div class="field"><label for="swarm-file">Load a UTF-8 text, JSON, or JavaScript file</label><input type="file" id="swarm-file" accept=".txt,.md,.json,.js,.mjs,.cjs"></div><div class="field"><label for="swarm-name">Source name</label><input id="swarm-name" value="source.txt"></div><div class="field"><label for="swarm-source">Full source</label><textarea id="swarm-source" rows="10" placeholder="Paste your source text here, or choose a file above."></textarea></div><div class="field"><label for="swarm-route">Destination</label><select id="swarm-route"><option value="auto">Automatic: code → build, numbers → experiments, text → library</option><option value="build">Build review queue</option><option value="experiments">Auto Lab evidence</option><option value="papers">Research paper draft</option><option value="library">Source library</option></select></div><label class="row"><input id="swarm-approved" type="checkbox"> I approve this local analysis.</label><div class="row"><button class="button" id="swarm-run">Run five-field analysis</button><button class="button secondary" id="swarm-refresh">Load saved findings</button></div><p id="swarm-message" class="error" role="status">${esc(message)}</p></section><section><h2>Recorded findings and routing</h2><div class="field"><label for="paper-repo">Approved paper destination repository</label><input id="paper-repo" value="justappgrabbin/Stellarproximology-lab"></div><div class="field"><label for="paper-destination">Paper release destination</label><select id="paper-destination"><option value="github">GitHub Release</option><option value="github-pages">GitHub Release + project page (replaces current Pages site)</option><option value="download">Local download</option></select></div><div id="swarm-results">${results()}</div></section></div>`;}
function readable(report){
 const stat=report.statistics, rows=Object.values(report.fields).map(f=>`<tr><td>${esc(f.field)}</td><td>${f.byteCount} bytes</td><td>${f.statistics.count} values</td><td>${f.statistics.mean==null?'—':Number(f.statistics.mean).toPrecision(5)}</td></tr>`).join('');
 return `<p><b>Full source reconstructed and verified.</b> ${report.bytes} bytes processed in five execution partitions.</p>${stat.count?`<p>${stat.count} numeric values · Total ${esc(stat.sum)} · Average ${esc(stat.mean)} · Range ${esc(stat.min)}–${esc(stat.max)}</p>`:''}<table><thead><tr><th>Partition</th><th>Work processed</th><th>Measurements</th><th>Average</th></tr></thead><tbody>${rows}</tbody></table><h3>Findings</h3>${report.findings.length?report.findings.map(f=>`<p>${esc(f.message)}</p>`).join(''):'<p>No issues were flagged by these checks.</p>'}<h3>Next actions</h3>${report.followUps.length?report.followUps.map(f=>`<p>${esc(f.action)} · Awaiting review</p>`).join(''):'<p>Review the recorded result in its destination workspace.</p>'}<details><summary>Source verification</summary><p class="small" style="overflow-wrap:anywhere">Source fingerprint: ${esc(report.sourceHash)}<br>Destination: ${esc(report.route)}</p></details>`;
}
function results(){return records.slice().reverse().map(r=>`<article class="note"><div class="row spread"><b>${esc(r.name)}</b><span class="pill">${esc(r.route)} · review</span></div>${readable(r.report)}<button class="button secondary" data-export-analysis="${r.id}">Save readable report</button>${r.route==='papers'?`<button class="button secondary" data-stage-paper="${r.id}">Prepare paper for publishing review</button>`:''}<p class="small muted">The findings are saved locally. Build changes and publication need approval.</p></article>`).join('')||'<div class="empty">Choose a source and run analysis. The results and next actions will appear here.</div>';}
function reportText(r){const s=r.report.statistics;return '# '+r.name+'\n\nFull source reconstructed and verified.\n\n'+Object.values(r.report.fields).map(f=>f.field+': '+f.byteCount+' bytes processed; '+f.statistics.count+' measurements').join('\n')+'\n\n'+(s.count?'Measurements: '+s.count+'\nTotal: '+s.sum+'\nAverage: '+s.mean+'\n':'')+'\nFindings\n'+(r.report.findings.map(f=>f.message).join('\n')||'No issues flagged by these checks.')+'\n\nNext actions\n'+r.report.followUps.map(f=>f.action).join('\n')+'\n\nDestination: '+r.route+'\nSource fingerprint: '+r.sourceHash;}
async function request(path,payload){const status=await fetch('/api/local/status').then(r=>r.json());if(!status.local)throw Error('Start the local service first.');const response=await fetch('/api/local/'+path,{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json','X-Local-Approval':status.token}:{},body:payload?JSON.stringify(payload):undefined,signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Analysis failed.');return data;}
export function bindSwarm(render){if(!document.querySelector('#swarm-run'))return;const say=text=>{message=text;document.querySelector('#swarm-message').textContent=text;};document.querySelector('#swarm-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>200000)throw Error('Maximum source size: 200,000 bytes.');const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());document.querySelector('#swarm-name').value=file.name;document.querySelector('#swarm-source').value=text;}catch(error){say(error.message);}};document.querySelector('#swarm-refresh').onclick=async()=>{try{records=(await request('analyses')).analyses;message='';render();}catch(error){say(error.message);}};document.querySelector('#swarm-run').onclick=async e=>{e.target.disabled=true;try{await request('analyze',{name:document.querySelector('#swarm-name').value,text:document.querySelector('#swarm-source').value,route:document.querySelector('#swarm-route').value,approved:document.querySelector('#swarm-approved').checked});records=(await request('analyses')).analyses;message='Findings saved and routed to local review.';render();}catch(error){say(error.message);e.target.disabled=false;}};document.querySelectorAll('[data-stage-paper]').forEach(button=>button.onclick=async()=>{try{await request('releases',{analysis:button.dataset.stagePaper,target:document.querySelector('#paper-destination').value,repo:document.querySelector('#paper-repo').value.trim()});say('Paper bundle staged. Open Publishing Studio, refresh, inspect it, and approve the exact release.');}catch(error){say(error.message);}});document.querySelectorAll('[data-export-analysis]').forEach(button=>button.onclick=()=>{const record=records.find(r=>r.id===button.dataset.exportAnalysis),url=URL.createObjectURL(new Blob([reportText(record)],{type:'text/markdown'})),a=document.createElement('a');a.href=url;a.download='synthia-analysis-'+record.id+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
